class Solution {
    fun areSentencesSimilar(sentence1:String,sentence2:String):Boolean{
        var first=sentence1.split(' ');
        var second=sentence2.split(' ');
        if(first.size>second.size){
            val temporary=first;
            first=second;
            second=temporary
        };
        var prefix=0;
        while(prefix<first.size&&first[prefix]==second[prefix])prefix++;
        var suffix=0;
        while(prefix+suffix<first.size&&first[first.lastIndex-suffix]==second[second.lastIndex-suffix])suffix++;
        return prefix+suffix==first.size
    }
}

code.cpp:
class Solution {
    public: bool areSentencesSimilar(string sentence1,string sentence2){
        auto split=[](string text){
            stringstream stream(text);
            vector<string> words;
            string word;
            while(stream>>word)words.push_back(word);
            return words;
        };
        auto first=split(sentence1),second=split(sentence2);
        if(first.size()>second.size())swap(first,second);
        int prefix=0;
        while(prefix<(int)first.size()&&first[prefix]==second[prefix])++prefix;
        int suffix=0;
        while(prefix+suffix<(int)first.size()&&first[first.size()-1-suffix]==second[second.size()-1-suffix])++suffix;
        return prefix+suffix==first.size();
    }
};
